# Generated by manage.py generate_test_cases.
"""Exercise visitor details and event-side booking origin without time duplication."""

from django.db.models.deletion import ProtectedError

from bloomerp.models.communication.calendar import (
    CalendarBookingSubmission,
    CalendarEvent,
)
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import CalendarFixtures


class TestCalendarBookingSubmissionModel(CalendarFixtures, BloomerpModelTestCase):
    model = CalendarBookingSubmission

    def get_test_scenarios(self) -> list[ModelScenario[CalendarBookingSubmission]]:
        """Cover event origin and deletion protection for retained booking details."""
        return [
            ModelScenario(
                name="Event references submission shared across inbox placements",
                preparation=self.prepare,
                create_args=self.submission_args,
                post_create=self.create_event,
                create_validators=self.has_event,
                expected_exceptions=[ExpectedModelException("delete", ProtectedError)],
            ),
        ]

    def create_event(self, submission: CalendarBookingSubmission) -> None:
        """Create one event referencing its origin and place it in two inboxes."""
        event = CalendarEvent.objects.create(
            **self.event_args(calendar_booking_submission=submission)
        )
        event.inboxes.add(self.inbox, self.team_inbox)

    def has_event(self, submission: CalendarBookingSubmission) -> bool:
        """Verify reverse event access, retained visitor details, and submission time."""
        return (
            submission.calendar_event.inboxes.count() == 2
            and submission.calendar_booking_id == self.booking.pk
            and submission.submitted_at is not None
            and submission.name == "Visitor"
        )
